def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, height in enumerate(a):
        rank = ranks[height]

        prefix = 0
        index = rank
        while index:
            prefix += tree[index]
            index -= index & -index

        result.append(min(i, k) - prefix)

        index = rank
        while index <= size:
            tree[index] += 1
            index += index & -index

        if i >= k:
            index = ranks[a[i - k]]
            while index <= size:
                tree[index] -= 1
                index += index & -index

    return result
